{
  "instruction": "Explain overfitting in machine learning.",
  "input": "Use a simple example.",
  "output": "Overfitting occurs when a model learns the training examples too closely and performs poorly on new data. For example, a student who memorizes practice questions but cannot solve new questions has overfit the practice set."
}

examples = [
    {"instruction": "Define entropy.", "output": "Entropy measures uncertainty in a probability distribution."},
    {"instruction": "Define overfitting.", "output": "Overfitting occurs when a model fits training data too closely."}
]

for example in examples:
    assert example["instruction"].strip()
    assert example["output"].strip()
    print("Instruction:", example["instruction"])
    print("Target:", example["output"], "\n")
